     5	/** Blocks messages to invalid e-mail addresses. */
     6	public final class EmailValidationRule implements MessageRule {
     7	
     8	    @Override
     9	    public List<OutgoingMessage> process(OutgoingMessage message) {
    10	        if (!isValidEmail(message.to())) {
    11	            message.block();
