     6	/** Applies a sequence of rules to an outgoing message. */
     7	public final class MessageRuleChain {
     8	
     9	    private final List<MessageRule> rules;
    10	
    11	    public MessageRuleChain(List<MessageRule> rules) {
    12	        this.rules = List.copyOf(rules);
    13	    }
    14	
    15	    /**
    16	     * Processes a message through all rules. Returns all messages that result from the processing
    17	     * (the original, possibly modified or blocked, plus any additional messages like archive copies).
    18	     */
    19	    public List<OutgoingMessage> process(OutgoingMessage message) {
    20	        List<OutgoingMessage> current = List.of(message);
    21	        for (MessageRule rule : rules) {
    22	            List<OutgoingMessage> next = new ArrayList<>();
    23	            for (OutgoingMessage msg : current) {
    24	                next.addAll(rule.process(msg));
    25	            }
    26	            current = next;
    27	        }
    28	        return current;
    29	    }
