    16	    private boolean isValidEmail(String email) {
    17	        if (email == null || email.isBlank()) {
    18	            return false;
    19	        }
    20	        long atCount = email.chars().filter(c -> c == '@').count();
    21	        if (atCount != 1) {
    22	            return false;
    23	        }
    24	        int atIndex = email.indexOf('@');
    25	        if (atIndex == 0) {
    26	            return false;
    27	        }
    28	        String domain = email.substring(atIndex + 1);
    29	        return domain.contains(".");
    30	    }
